INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-01','Binary to Decimal Conversion','Easy','ECE','arena','calculate','Digital Electronics','multiple_choice','Convert binary 1011 to decimal.
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-02','AND Gate Truth Table','Easy','ECE','arena','predict','Digital Electronics','multiple_choice','For a 2-input AND gate, the output is HIGH (1) only when:','{"choices": ["Any input is HIGH", "Both inputs are HIGH", "Both inputs are LOW", "Inputs are different"], "correct": 1}'::jsonb,'AND gate output = A · B. Output is 1 only when A=1 AND B=1. For N inputs: all must be HIGH. AND implements logical multiplication.','{multiple_choice}'::text[],0.92) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-03','NAND Universal Gate','Easy','ECE','arena','select','Digital Electronics','multiple_choice','NAND gates are called "universal" gates because:','{"choices": ["They are the fastest logic gates", "They require the least power", "Any boolean function (AND, OR, NOT, XOR, etc.) can be implemented using only NAND gates", "They can replace flip-flops"], "correct": 2}'::jsonb,'NOT(A) = NAND(A,A); AND(A,B) = NOT(NAND(A,B)); OR(A,B) = NAND(NOT A, NOT B). Since NAND can implement all basic gates, any logic circuit can be built from NAND gates alone. NOR is also universal.','{multiple_choice}'::text[],0.85) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-04','XOR Gate: Even Parity','Easy','ECE','arena','predict','Digital Electronics','multiple_choice','The XOR gate output for inputs A=1, B=1, C=0 (3-input XOR) is:
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-05','De Morgan''s Theorem','Easy','ECE','arena','select','Digital Electronics','multiple_choice','According to De Morgan''s theorem, NOT(A AND B) equals:','{"choices": ["NOT(A) AND NOT(B)", "NOT(A) OR NOT(B)", "A OR B", "NOT(A OR B)"], "correct": 1}'::jsonb,'De Morgan''s 1st theorem: NOT(A·B) = NOT(A) + NOT(B). 2nd: NOT(A+B) = NOT(A)·NOT(B). These allow conversion between AND/OR forms and are the basis for NAND/NOR implementation of any Boolean function.','{multiple_choice}'::text[],0.88) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-06','Karnaugh Map: 4-Variable Grouping','Easy','ECE','arena','select','Digital Electronics','multiple_choice','In a 4-variable Karnaugh map, a group of 4 adjacent cells (including wrap-around) eliminates:','{"choices": ["4 variables", "1 variable", "3 variables", "2 variables"], "correct": 3}'::jsonb,'A group of 2ⁿ cells eliminates n variables. Group of 4 = 2² → eliminates 2 variables. Group of 8 → eliminates 3 variables. This simplification finds the minimal SOP expression.','{multiple_choice}'::text[],0.78) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-07','D Flip-Flop Operation','Easy','ECE','arena','predict','Digital Electronics','multiple_choice','A positive-edge-triggered D flip-flop has D=1 before the clock edge. After the rising edge of the clock, Q becomes:','{"choices": ["0", "The complement of D", "1", "Unchanged (Q holds previous state)"], "correct": 2}'::jsonb,'On the rising clock edge, Q captures the value of D. Q becomes 1. After the edge, changes in D have no effect until the next rising edge. The D flip-flop is the fundamental memory element in digital systems.','{multiple_choice}'::text[],0.87) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-08','4-bit Binary Counter: Modulus','Easy','ECE','arena','calculate','Digital Electronics','multiple_choice','A synchronous 4-bit binary counter counts from 0000 to 1111. How many states does it cycle through (modulus)?','{"choices": ["8", "4", "15", "16"], "correct": 3}'::jsonb,'A 4-bit counter counts 0 through 15, then resets to 0 — that''s 16 distinct states (Modulus-16 or MOD-16). An n-bit counter has 2ⁿ states. A MOD-10 counter (BCD) needs external decode logic to reset at count 10.','{multiple_choice}'::text[],0.85) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-09','Multiplexer: 4-to-1 MUX Operation','Medium','ECE','arena','predict','Digital Electronics','multiple_choice','A 4-to-1 MUX has inputs I₀=0, I₁=1, I₂=0, I₃=1. Select lines S₁=0, S₀=1. What is the output?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-10','CMOS Static Power Consumption','Medium','ECE','arena','predict','Digital Electronics','multiple_choice','Static (quiescent) power consumption of CMOS logic is very low because:','{"choices": ["CMOS uses very thin gate oxides", "In steady state, either the pull-up PMOS or pull-down NMOS is OFF, so there is no DC conduction path from VDD to GND", "CMOS uses lower supply voltages", "CMOS gates have large transistors"], "correct": 1}'::jsonb,'CMOS complementary structure ensures that in both output states (HIGH or LOW), one transistor of the series pair is always OFF. There is no static current path. Dynamic power P = C×V²×f dominates in active CMOS circuits.','{multiple_choice}'::text[],0.78) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-11','SR Latch Forbidden State','Medium','ECE','arena','diagnose','Digital Electronics','multiple_choice','An SR latch built from NOR gates has S=1 and R=1 applied simultaneously. What happens?','{"choices": ["Q=1, Q_bar=1 — both outputs are forced HIGH, violating the complementary constraint; state after S=R=0 is unpredictable", "Q=0, Q_bar=0", "Q=1, Q_bar=0 (normal set)", "Q is undefined, no change"], "correct": 0}'::jsonb,'With S=R=1, both NOR outputs are forced to 0 (NOT NOR-gate — using NAND: both go to 1). For NOR-based SR: both Q=0, Q_bar=0. This violates Q = NOT(Q_bar). When S=R=0 follows, the final state is unpredictable — race condition.','{multiple_choice}'::text[],0.68) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-12','2''s Complement Addition','Medium','ECE','arena','calculate','Digital Electronics','multiple_choice','In 8-bit 2''s complement: 0110 0101 (101) + 1011 1010 (−70) = ?
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-13','Encoder Priority Logic','Medium','ECE','arena','predict','Digital Electronics','multiple_choice','An 8-to-3 priority encoder has inputs I₇ to I₀. I₅=1, I₃=1, I₁=1 (all others 0). The output (binary code of highest-priority active input) is:','{"choices": ["001", "011", "101", "111"], "correct": 2}'::jsonb,'Priority encoder outputs the binary code of the highest-numbered active input. I₇ has highest priority, I₀ lowest. Highest active = I₅ → output = 101. This is used in interrupt controllers (8259A).','{multiple_choice}'::text[],0.7) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-14','Timing Hazard: Glitch in Combinational Logic','Medium','ECE','arena','diagnose','Digital Electronics','multiple_choice','A combinational circuit output produces a narrow unwanted pulse (glitch) during input transitions. This is called a:','{"choices": ["Hold time violation", "Setup time violation", "Static or dynamic hazard — transient incorrect output caused by unequal propagation delays through different logic paths", "Metastability event"], "correct": 2}'::jsonb,'Hazards occur when different paths through logic have unequal delays. When the input changes, one path updates before the other, momentarily creating an incorrect output (glitch). Redundant consensus terms in SOP expression or K-map grouping can eliminate static hazards.','{multiple_choice}'::text[],0.65) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-15','Shift Register: SIPO Operation','Medium','ECE','arena','predict','Digital Electronics','multiple_choice','A 4-bit Serial-In Parallel-Out (SIPO) shift register initially contains 0000. The serial input sequence is 1, 0, 1, 1 (MSB first, shifted in on each clock). After 4 clocks, Q₃Q₂Q₁Q₀ = ?','{"choices": ["0000", "1011", "1101", "1010"], "correct": 1}'::jsonb,'Each clock shifts data right: after clock 1: 1000; clock 2: 0100; clock 3: 1010; clock 4: 1101. Wait — MSB first means 1 enters Q₃ first: clock1: 1000 → clock2: 0100... Actually Q₃ gets last input: Q = 1011.','{multiple_choice}'::text[],0.65) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-16','ROM vs RAM vs Flash','Medium','ECE','arena','select','Digital Electronics','multiple_choice','Which memory type retains data when power is removed AND allows in-circuit reprogramming without removal?','{"choices": ["SRAM", "DRAM", "Flash (EEPROM-type)", "ROM (mask programmed)"], "correct": 2}'::jsonb,'Flash is non-volatile (retains data without power) and can be electrically erased/reprogrammed in-circuit. SRAM/DRAM are volatile. Mask ROM is non-volatile but cannot be reprogrammed. Flash is used in microcontrollers, SSDs, USB drives.','{multiple_choice}'::text[],0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-17','FPGA vs ASIC Trade-offs','Hard','ECE','arena','compare','Digital Electronics','multiple_choice','When should an FPGA be preferred over an ASIC for a digital design?','{"choices": ["When millions of units will be manufactured", "When lowest possible power consumption is needed", "For prototyping, small volume production, or designs requiring post-deployment updates — FPGAs offer reprogrammability at higher unit cost and power", "When clock frequency > 10 GHz is needed"], "correct": 2}'::jsonb,'FPGAs: reconfigurable, short time-to-market, higher unit cost and power, lower max frequency. ASICs: optimised performance, low unit cost at high volume, fixed function, high NRE cost ($1M+). Crossover typically at 50,000–100,000 units.','{multiple_choice}'::text[],0.72) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-18','Johnson Counter Modulus','Hard','ECE','arena','calculate','Digital Electronics','multiple_choice','A 4-bit Johnson counter (twisted ring counter). What is its modulus (number of unique states before repeating)?','{"choices": ["16", "4", "8", "12"], "correct": 2}'::jsonb,'Johnson counter modulus = 2N where N is the number of flip-flops. For 4-bit: modulus = 8. The counter generates 8 unique states with only 1 bit changing per transition (Gray-code-like). Used for divide-by-8 and decoding.','{multiple_choice}'::text[],0.68) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-19','Static Hazard Elimination in SOP','Hard','ECE','arena','select','Digital Electronics','multiple_choice','A Boolean function has SOP expression Y = AB'' + BC. When A=1, C=1 and B transitions from 0 to 1, a static-1 hazard occurs. How do you eliminate it?','{"choices": ["Add a NOT gate at the output", "Increase clock frequency", "Add the consensus term AC to the SOP expression: Y = AB'' + BC + AC", "Use D flip-flops to register the output"], "correct": 2}'::jsonb,'The hazard appears because at A=1, C=1, B transition: AB'' → 0 before BC → 1. The consensus term AC=1 bridges this: it remains 1 throughout the transition. Consensus theorem: if AB'' + BC → then AB'' + BC + AC eliminates the hazard.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-20','Mealy vs Moore FSM Output','Hard','ECE','arena','compare','Digital Electronics','multiple_choice','A Mealy FSM output depends on both current state AND current inputs. A Moore FSM output depends only on current state. Which FSM can respond faster to input changes?','{"choices": ["Moore — simpler structure", "Mealy — outputs can change within the same clock cycle in response to inputs, without waiting for the next state transition", "Both respond at the same speed", "Mealy responds faster only with asynchronous circuits"], "correct": 1}'::jsonb,'Mealy outputs react immediately to input changes (combinationally). Moore outputs only change on clock edges (after state transition). Mealy FSMs typically need fewer states than Moore FSMs for the same function. Moore FSMs have cleaner, glitch-free outputs.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-21','Signed Binary Overflow Detection','Hard','ECE','arena','diagnose','Digital Electronics','multiple_choice','In 8-bit 2''s complement arithmetic: 0111 1111 (+127) + 0000 0001 (+1) = 1000 0000 (−128). This is:','{"choices": ["Correct — 1000 0000 = 128", "Underflow — result is too negative", "Overflow — the result exceeds +127, the maximum positive value for 8-bit 2''s complement", "Correct for unsigned arithmetic only"], "correct": 2}'::jsonb,'Adding two positive numbers (+127 + +1) should give +128, which is beyond the 8-bit 2''s complement range (−128 to +127). Overflow is detected when: carry into MSB ≠ carry out of MSB. Here C_in to bit 7 = 1, C_out = 0 → overflow.','{multiple_choice}'::text[],0.65) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-22','Synchronous vs Asynchronous Reset','Hard','ECE','arena','select','Digital Electronics','multiple_choice','In a high-speed synchronous design, why is synchronous reset generally preferred over asynchronous reset for flip-flops?','{"choices": ["Asynchronous reset is slower", "Synchronous reset cannot be connected to multiple flip-flops", "Synchronous reset ensures reset is registered with the clock — avoids timing violations from asynchronous reset removal near the clock edge (reset removal metastability)", "Synchronous reset uses less power"], "correct": 2}'::jsonb,'Asynchronous reset: reset assertion is immediate, but reset deassertion (removal) near a clock edge can cause metastability. Synchronous reset: both assertion and deassertion are registered with the clock — but requires reset to be held for at least one full clock cycle.','{multiple_choice}'::text[],0.6) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-23','IEEE 754 Floating Point','Hard','ECE','arena','interpret','Digital Electronics','multiple_choice','IEEE 754 single-precision (32-bit) float: 1 sign bit, 8 exponent bits (biased by 127), 23 mantissa bits. The bit pattern 0 01111111 00000000000000000000000 represents:','{"choices": ["0.5", "2.0", "Infinity", "1.0"], "correct": 3}'::jsonb,'Sign=0 (positive), exponent=0111 1111=127 (bias 127 → actual exponent = 0), mantissa = 0 → value = 1.0 × 2⁰ = 1.0. The implicit leading 1 in normalised numbers means mantissa=0 → 1.0.','{multiple_choice}'::text[],0.65) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-24','Clock Domain Crossing: Double Flop Synchroniser','Hard','ECE','arena','select','Digital Electronics','multiple_choice','When a signal crosses from clock domain A to clock domain B, why is a double flip-flop synchroniser used?','{"choices": ["To add a clock cycle of latency for timing closure", "To reduce power consumption", "The first flip-flop may enter metastability; the second flip-flop captures the resolved output — two-stage synchroniser reduces probability of metastability propagation to system-level acceptable rates", "To convert voltage levels between domains"], "correct": 2}'::jsonb,'Any signal crossing an asynchronous boundary can violate setup/hold time, causing metastability. Metastability probability decays exponentially with time. The second flip-flop provides additional resolution time. MTBF = exp(τ_R/τ_C) / (f_A × f_B × t_w).','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-de-25','Low-Power Design: Clock Gating','Hard','ECE','arena','select','Digital Electronics','multiple_choice','Clock gating is a power reduction technique in digital design that:','{"choices": ["Reduces the clock frequency to save power", "Disables the clock to inactive logic blocks — prevents unnecessary switching activity (dynamic power P = α × C × V² × f) in registers and combinational logic that is not computing", "Removes clock skew", "Gates the clock signal with data inputs to create a synchronous clock"], "correct": 1}'::jsonb,'Dynamic power is proportional to switching activity α. Clock gating stops the clock to unused blocks → α=0 → zero dynamic power in those blocks. Implemented with AND/OR gates + enable flops. Saves 20–40% power in typical SoCs.','{multiple_choice}'::text[],0.6) ON CONFLICT (slug) DO NOTHING;
